<?php authorizeAdmin($u); ?><p class="page-intro">Las novedades se guardan en una cola. El envío requiere configurar SMTP y ejecutar el trabajador de correo indicado en el manual.</p><?php if(!$GLOBALS['config']['smtp']['host']): ?><div class="alert warning">SMTP pendiente de configurar. Los correos se conservan en la cola y todavía no se han enviado.</div><?php endif; ?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Destinatario</th><th>Asunto</th><th>Estado</th><th>Intentos</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM outbox ORDER BY id DESC LIMIT 200') as $m): ?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['recipient'])?></td><td><?=e($m['subject'])?></td><td><?=badge($m['status'])?></td><td><?=(int)$m['attempts']?></td></tr><?php endforeach; ?></tbody></table></div></section>
